import{_ as t,o,c as i,a2 as n}from"./chunks/framework.DnrXFDHb.js";const m=JSON.parse('{"title":"infrastructure/output — 输出适配器总览","description":"OutputSink 实现、自动 MIDI 录制、metronome 与组合关系","frontmatter":{"title":"infrastructure/output — 输出适配器总览","description":"OutputSink 实现、自动 MIDI 录制、metronome 与组合关系"},"headers":[],"relativePath":"architecture/infrastructure/output/overview.md","filePath":"architecture/infrastructure/output/overview.md","lastUpdated":1773326634000}'),a={name:"architecture/infrastructure/output/overview.md"};function d(s,e,c,r,u,p){return o(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="infrastructure-output-—-输出适配器总览" tabindex="-1">infrastructure/output — 输出适配器总览 <a class="header-anchor" href="#infrastructure-output-—-输出适配器总览" aria-label="Permalink to &quot;infrastructure/output — 输出适配器总览&quot;">​</a></h1><p><strong>源文件</strong>：<code>src/streammuse/infrastructure/output/</code></p><p>所有输出适配器均实现 <code>OutputSink</code> 协议（见 <a href="./../../domain/interfaces.html">domain/interfaces</a>）。部分适配器额外实现 <code>log_inference()</code> 或 <code>output_metronome_tick()</code>，服务层通过 <code>hasattr</code> 检测调用。</p><hr><h2 id="用户可选输出类型" tabindex="-1">用户可选输出类型 <a class="header-anchor" href="#用户可选输出类型" aria-label="Permalink to &quot;用户可选输出类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类</th><th>CLI 类型</th><th>说明</th></tr></thead><tbody><tr><td><code>ConsoleOutputSink</code></td><td><code>console</code></td><td>将事件和统计信息打印到终端</td></tr><tr><td><code>AudioOutputSink</code></td><td><code>audio</code></td><td>向 MIDI 输出端口发送模型音符，实现实时播放</td></tr><tr><td><code>MidiFileOutputSink</code></td><td><code>midi_file</code></td><td>将事件流录制为 MIDI 文件</td></tr><tr><td><code>WebSocketOutputSink</code></td><td><code>websocket</code></td><td>将事件序列化为 JSON，入队供 WebSocket 推送</td></tr><tr><td><code>JsonLoggerOutputSink</code></td><td><code>json_log</code></td><td>写入 <code>events.jsonl</code> 和 <code>inferences.json</code></td></tr><tr><td><code>SessionLoggerOutputSink</code></td><td><code>session</code></td><td>组合 MIDI 录制和 JSON 日志，写入会话目录</td></tr><tr><td><code>CompositeOutputSink</code></td><td><code>composite</code></td><td>将调用 fan-out 到多个子 sink</td></tr></tbody></table><p><code>MetronomeOutputSink</code> 是辅助 sink，由 <code>--enable-metronome</code> 附加，不作为 <code>--output-type</code> 的可选值。</p><hr><h2 id="组合关系" tabindex="-1">组合关系 <a class="header-anchor" href="#组合关系" aria-label="Permalink to &quot;组合关系&quot;">​</a></h2><p><code>--output-type composite</code> 且有 session manager 时：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CompositeOutputSink</span></span>
<span class="line"><span> ├── ConsoleOutputSink</span></span>
<span class="line"><span> └── SessionLoggerOutputSink</span></span>
<span class="line"><span>      ├── MidiFileOutputSink  → combined.mid</span></span>
<span class="line"><span>      └── JsonLoggerOutputSink → events.jsonl, inferences.json</span></span></code></pre></div><p><code>console</code> / <code>audio</code> / <code>websocket</code> 且有 session manager 时，工厂会自动附加 MIDI 录制：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CompositeOutputSink</span></span>
<span class="line"><span> ├── &lt;base sink&gt;</span></span>
<span class="line"><span> └── MidiFileOutputSink → combined.mid</span></span></code></pre></div><p>开启 <code>--enable-metronome</code> 后，工厂会继续附加：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CompositeOutputSink</span></span>
<span class="line"><span> ├── ...existing sinks...</span></span>
<span class="line"><span> └── MetronomeOutputSink → live MIDI click</span></span></code></pre></div><p>同时，所有 <code>MidiFileOutputSink</code> 会用 <code>record_metronome=True</code> 记录 <code>Metronome</code> 鼓轨。</p><hr><h2 id="扩展方法" tabindex="-1">扩展方法 <a class="header-anchor" href="#扩展方法" aria-label="Permalink to &quot;扩展方法&quot;">​</a></h2><h3 id="log-inference" tabindex="-1"><code>log_inference()</code> <a class="header-anchor" href="#log-inference" aria-label="Permalink to &quot;\`log_inference()\`&quot;">​</a></h3><p>以下 sink 支持推理日志：</p><ul><li><code>JsonLoggerOutputSink</code></li><li><code>SessionLoggerOutputSink</code></li><li><code>CompositeOutputSink</code>（fan-out）</li></ul><h3 id="output-metronome-tick" tabindex="-1"><code>output_metronome_tick()</code> <a class="header-anchor" href="#output-metronome-tick" aria-label="Permalink to &quot;\`output_metronome_tick()\`&quot;">​</a></h3><p>以下 sink 支持 metronome tick：</p><ul><li><code>MetronomeOutputSink</code>：实时发送 MIDI drum note</li><li><code>MidiFileOutputSink</code>：写入 MIDI <code>Metronome</code> 轨</li><li><code>SessionLoggerOutputSink</code>：委托给内部 <code>midi_sink</code></li><li><code>CompositeOutputSink</code>：fan-out</li></ul><hr><h2 id="详细文档" tabindex="-1">详细文档 <a class="header-anchor" href="#详细文档" aria-label="Permalink to &quot;详细文档&quot;">​</a></h2><ul><li><a href="./console.html">console.md</a> — <code>ConsoleOutputSink</code></li><li><a href="./audio.html">audio.md</a> — <code>AudioOutputSink</code></li><li><a href="./midi_file.html">midi_file.md</a> — <code>MidiFileOutputSink</code></li><li><a href="./metronome.html">metronome.md</a> — <code>MetronomeOutputSink</code></li><li><a href="./websocket.html">websocket.md</a> — <code>WebSocketOutputSink</code></li><li><a href="./json_logger.html">json_logger.md</a> — <code>JsonLoggerOutputSink</code></li><li><a href="./session_logger.html">session_logger.md</a> — <code>SessionLoggerOutputSink</code></li><li><a href="./composite.html">composite.md</a> — <code>CompositeOutputSink</code></li></ul>`,27)])])}const h=t(a,[["render",d]]);export{m as __pageData,h as default};
